-- Owner-provided reference pricing, retaining Narfid plan names. Commercial allowances only; preserve IDs, account links and contract snapshots.
begin;
lock table public.crm_plans in share row exclusive mode;
do $guard$ begin
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"أساس","description":"بداية مرتّبة لناديك","pricing_type":"fixed","annual_fee_cents":180000,"setup_fee_cents":0,"features":["فرع واحد","حتى ١٬٠٠٠ عضو مسجّل","الأعضاء والاشتراكات والتجديد والتجميد","الحضور وحجوزات الملاعب والحصص","التدريب الشخصي والمدربون والقياسات","الخطط والبرامج التدريبية","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","جداول ودوام الموظفين","صلاحيات الفريق والتقارير","يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.","عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.","المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل"],"active":true,"sort_order":1,"revision":2}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"نمو","description":"مساحة أكبر لنمو عضويتك","pricing_type":"fixed","annual_fee_cents":330000,"setup_fee_cents":0,"features":["فرع واحد","حتى ٥٬٠٠٠ عضو مسجّل","الأعضاء والاشتراكات والتجديد والتجميد","الحضور وحجوزات الملاعب والحصص","التدريب الشخصي والمدربون والقياسات","الخطط والبرامج التدريبية","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","جداول ودوام الموظفين","صلاحيات الفريق والتقارير","يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.","عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.","المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل"],"active":true,"sort_order":2,"revision":2}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"احتراف","description":"للمؤسسة ذات العضوية الأكبر","pricing_type":"fixed","annual_fee_cents":420000,"setup_fee_cents":0,"features":["فرع واحد","حتى ١٠٬٠٠٠ عضو مسجّل","الأعضاء والاشتراكات والتجديد والتجميد","الحضور وحجوزات الملاعب والحصص","التدريب الشخصي والمدربون والقياسات","الخطط والبرامج التدريبية","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","جداول ودوام الموظفين","صلاحيات الفريق والتقارير","يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.","عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.","المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل"],"active":true,"sort_order":3,"revision":1}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"توسّع","description":"منظومة تنمو مع طموحك","pricing_type":"fixed","annual_fee_cents":660000,"setup_fee_cents":0,"features":["فرعان","حتى ١٠٬٠٠٠ عضو مسجّل إجمالًا عبر الفرعين","الأعضاء والاشتراكات والتجديد والتجميد","الحضور وحجوزات الملاعب والحصص","التدريب الشخصي والمدربون والقياسات","الخطط والبرامج التدريبية","نقاط البيع وورديات الصندوق","الفواتير والتحصيل والمرتجعات","جداول ودوام الموظفين","صلاحيات الفريق والتقارير","إدارة مركزية للفروع","صلاحيات وتشغيل حسب الفرع","تقارير مجمّعة لمتابعة الأداء","يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.","عند تجاوز حد الباقة نراجع معك الترقية ونمنح مهلة متفقًا عليها لاستكمالها؛ لا يتوقف التشغيل فورًا بسبب التجاوز.","المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل"],"active":true,"sort_order":4,"revision":2}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
  if not exists(select 1 from public.crm_plans p where to_jsonb(p) @> '{"name":"شراكة تقنية","description":"لتجاوز حدود الأعضاء المسجلين أو لثلاثة فروع فأكثر أو احتياج تقني خاص، دون اشتراط تطوير.","pricing_type":"custom","annual_fee_cents":null,"setup_fee_cents":0,"features":["عدد الأعضاء المسجلين والفروع ونطاق المنصة حسب الاتفاق","يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.","يمكن أن يقتصر الاتفاق على اشتراك المنصة والتهيئة والدعم","المنتجات والمخزون والمطبخ والوجبات إضافات اختيارية بعرض مستقل","التطبيقات والبوابات المتوافقة والتكاملات والتطوير اختيارية وتُسعّر منفصلة","تحديد الأجهزة ورسوم الأطراف الأخرى والصيانة بشكل مستقل"],"active":true,"sort_order":5,"revision":2}'::jsonb) then raise exception 'Pricing catalog changed since inspection; review before applying'; end if;
end $guard$;
update public.crm_plans set annual_fee_cents=144000,features=array['فرع واحد','حتى 1000 عضو مسجّل','يشمل 2 حسابات لفريق العمل','فريق العمل خارج حسابات الأعضاء','فواتير غير محدودة','نقاط البيع وورديات الصندوق','إدارة الأعضاء والاشتراكات','التجديد والتجميد والحضور','إدارة الخدمات والعروض','صلاحيات المستخدمين','الإيرادات والتحصيل والمرتجعات','إدارة المصروفات','التقارير','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.']::text[],sort_order=1 where name='أساس';
update public.crm_plans set annual_fee_cents=330000,features=array['فرع واحد','حتى 5000 عضو مسجّل','يشمل 5 حسابات لفريق العمل','فريق العمل خارج حسابات الأعضاء','فواتير غير محدودة','نقاط البيع وورديات الصندوق','طلبات الخدمات أونلاين','إدارة الأعضاء والاشتراكات','التجديد والتجميد والحضور','إدارة الخدمات والعروض','صلاحيات المستخدمين','الإيرادات والتحصيل والمرتجعات','إدارة المدربين','إدارة المصروفات','إدارة القياسات','البرامج التدريبية','التقارير','جداول ودوام الموظفين','المنتجات والمخزون','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.']::text[],sort_order=2 where name='نمو';
update public.crm_plans set annual_fee_cents=420000,features=array['فرع واحد','حتى 10000 عضو مسجّل','يشمل 10 حسابات لفريق العمل','فريق العمل خارج حسابات الأعضاء','فواتير غير محدودة','نقاط البيع وورديات الصندوق','طلبات الخدمات أونلاين','إدارة الأعضاء والاشتراكات','التجديد والتجميد والحضور','إدارة الخدمات والعروض','صلاحيات المستخدمين','الإيرادات والتحصيل والمرتجعات','إدارة المدربين','إدارة المصروفات','إدارة القياسات','البرامج التدريبية','التقارير','جداول ودوام الموظفين','المنتجات والمخزون','المطبخ واشتراكات الوجبات','يشمل العدد كل عضو مسجّل لدى المؤسسة، سواء كان اشتراكه ساريًا أو مجمّدًا أو منتهيًا، بما في ذلك ملفات الأعضاء القديمة. يُحسب العضو مرة واحدة مهما تعددت اشتراكاته أو الفروع التي يستخدمها؛ العملاء المحتملون قبل تسجيلهم كأعضاء خارج العدد.']::text[],sort_order=3 where name='احتراف';
