update public.crm_plans set description='لثلاثة فروع فأكثر أو احتياج تقني خاص، بعرض مستقل دون اشتراط تطوير.',features=array['اشتراك المنصة لثلاثة فروع فأكثر أو احتياج تقني خاص','يمكن أن يقتصر الاتفاق على اشتراك المنصة والتهيئة والدعم','توسّع تشمل أعضاء وحسابات فريق غير محدودة؛ الأعداد وحدها لا تستلزم الشراكة','التطبيقات والبوابات المتوافقة والتكاملات والتطوير اختيارية وتُسعّر منفصلة','تحديد الأجهزة ورسوم الأطراف الأخرى والصيانة بشكل مستقل']::text[],sort_order=5 where name='شراكة تقنية';
